   870  static enum lwan_read_finalizer
   871  read_request_finalizer(size_t total_read,
   872                         size_t buffer_size,
   873                         struct lwan_request_parser_helper *helper,
   874                         int n_packets)
   875  {
   876      /* 16 packets should be enough to read a request (without the body, as
   877       * is the case for POST requests).  This yields a timeout error to avoid
   878       * clients being intentionally slow and hogging the server.  */
   879      if (UNLIKELY(n_packets > helper->error_when_n_packets))
   880          return FINALIZER_ERROR_TIMEOUT;
   881
   882      if (UNLIKELY(total_read < 4))
   883          return FINALIZER_YIELD_TRY_AGAIN;
   884
   885      if (UNLIKELY(total_read == buffer_size))
   886          return FINALIZER_ERROR_TOO_LARGE;
   887
   888      char *crlfcrlf = memmem(helper->buffer->value, helper->buffer->len, "\r\n\r\n", 4);
   889      if (LIKELY(crlfcrlf)) {
   890          helper->crlfcrlf = crlfcrlf;
   891          return FINALIZER_DONE;
   892      }
   893
   894      if (LIKELY(helper->next_request)) {
   895          helper->next_request = NULL;
   896          return FINALIZER_DONE;
   897      }
   898
   899      return FINALIZER_TRY_AGAIN;
   900  }
