   910  static enum lwan_read_finalizer
   911  post_data_finalizer(size_t total_read,
   912                      size_t buffer_size,
   913                      struct lwan_request_parser_helper *helper,
   914                      int n_packets)
   915  {
   916      if (buffer_size == total_read)
   917          return FINALIZER_DONE;
   918
   919      /* For POST requests, the body can be larger, and due to small MTUs on
   920       * most ethernet connections, responding with a timeout solely based on
   921       * number of packets doesn't work.  Use keepalive timeout instead.  */
   922      if (UNLIKELY(time(NULL) > helper->error_when_time))
   923          return FINALIZER_ERROR_TIMEOUT;
   924
   925      /* In addition to time, also estimate the number of packets based on an
   926       * usual MTU value and the request body size.  */
   927      if (UNLIKELY(n_packets > helper->error_when_n_packets))
   928          return FINALIZER_ERROR_TIMEOUT;
   929
   930      return FINALIZER_TRY_AGAIN;
   931  }
